function srgbToLin(c) { const v = c / 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }
function lum(r, g, b) { return 0.2126 * srgbToLin(r) + 0.7152 * srgbToLin(g) + 0.0722 * srgbToLin(b); }
function parseHex(h) { h = h.replace('#',''); return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)]; }
function blend(fg, fa, bg, ba) { const a = fa + ba * (1 - fa); return [(fg[0]*fa + bg[0]*ba*(1-fa))/a, (fg[1]*fa + bg[1]*ba*(1-fa))/a, (fg[2]*fa + bg[2]*ba*(1-fa))/a, a]; }
function lin(p) { return lum(p[0], p[1], p[2]); }
function ratio(l1, l2) { return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05); }

const cases = [
  ['light glass', '#EDF3FB', 0, 0, 0, 0.04, '#0F172A'],
  ['light neo',   '#E7EBF2', 0, 0, 0, 0.04, '#1E2933'],
  ['light mono',  '#F4F4F2', 0, 0, 0, 0.04, '#0A0A0A'],
  ['dark glass',  '#06080D', 255, 255, 255, 0.045, '#F1F5F9'],
  ['dark neo',    '#181B21', 255, 255, 255, 0.045, '#E7EBF2'],
  ['dark mono',   '#000000', 255, 255, 255, 0.045, '#F5F5F5'],
];

for (const [name, bgHex, tr, tg, tb, ta, textHex] of cases) {
  const bg = parseHex(bgHex);
  const card = blend([tr, tg, tb], ta, bg, 1);
  const Lbg = lin(bg), Lcard = lin(card), Ltext = lin(parseHex(textHex));
  const cardPx = card.map(v => Math.round(v)).map(v => v.toString(16).padStart(2, '0')).join('');
  console.log(
    name.padEnd(12),
    'card ~#' + cardPx,
    'cardΔL=' + Math.abs(Lbg - Lcard).toFixed(4),
    'textRatio=' + ratio(Lbg, Ltext).toFixed(2) + ':1'
  );
}
